    result = top_n([5, 1, 9, 3, 7], 3)
    assert result == [9, 7, 5], f"expected [9, 7, 5] got {result}"


def test_n_zero_returns_empty():
    assert top_n([1, 2, 3], 0) == []


def test_n_larger_than_input_returns_all_descending():
    result = top_n([2, 1], 10)
    assert result == [2, 1], f"expected [2, 1] got {result}"


def test_duplicates_preserved():
    result = top_n([5, 5, 3, 1], 3)
    assert result == [5, 5, 3], f"expected [5,5,3] got {result}"


def test_type_error_on_non_list():
    try:
        top_n("not a list", 2)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_type_error_on_non_int_values():
    try:
        top_n([1, 2.5, 3], 2)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_value_error_on_negative_n():
    try:
        top_n([1, 2, 3], -1)
        assert False, "expected ValueError"
    except ValueError:
        pass

