import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
moving_average = target.moving_average


def test_basic_five_values_window_three():
    # Spec: "For a window of 3 over five values, return three averages:
    # positions 0..2, 1..3, and 2..4."
    values = [1, 2, 3, 4, 5]
    result = moving_average(values, 3)
    assert len(result) == 3
    assert result == [2.0, 3.0, 4.0]


def test_window_larger_than_input_returns_empty():
    values = [1, 2, 3]
    result = moving_average(values, 5)
    assert result == []


def test_window_equal_to_length_returns_single_average():
    values = [2, 4, 6]
    result = moving_average(values, 3)
    assert len(result) == 1
    assert result[0] == 4.0


def test_window_one_returns_each_value_rounded():
    values = [1, 2, 3]
    result = moving_average(values, 1)
    assert result == [1.0, 2.0, 3.0]


def test_rounding_half_up_behavior():
    # average of [1, 2] = 1.5 -> rounded to 1.5 (no rounding needed here)
    # use a case that requires rounding: [1, 2, 2] window 3 -> avg = 1.6666...
    values = [1, 2, 2]
    result = moving_average(values, 3)
    assert len(result) == 1
    assert result[0] == 1.67


def test_invalid_values_type_raises_type_error():
    try:
        moving_average("not a list", 2)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_invalid_element_type_raises_type_error():
    try:
        moving_average([1, "two", 3], 2)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_invalid_window_type_raises_type_error():
    try:
        moving_average([1, 2, 3], 2.5)
        assert False, "expected TypeError"
    except TypeError:
        pass


def test_non_positive_window_raises_value_error():
    try:
        moving_average([1, 2, 3], 0)
        assert False, "expected ValueError"
    except ValueError:
        pass

    try:
        moving_average([1, 2, 3], -1)
        assert False, "expected ValueError"
    except ValueError:
        pass

